const storageTotals = `-- name: StorageTotals :one
SELECT COALESCE(SUM(used_bytes), 0)::bigint AS total_used, COUNT(*)::int AS user_count
FROM users WHERE status <> 'deleted'
`

type StorageTotalsRow struct {
	TotalUsed int64
	UserCount int32
}

func (q *Queries) StorageTotals(ctx context.Context) (StorageTotalsRow, error) {
	row := q.db.QueryRow(ctx, storageTotals)
	var i StorageTotalsRow
	err := row.Scan(&i.TotalUsed, &i.UserCount)
	return i, err
}

const topConsumers = `-- name: TopConsumers :many
SELECT id, username, used_bytes, COALESCE(quota_bytes_override, $1::bigint)::bigint AS quota_bytes
FROM users WHERE status <> 'deleted'
ORDER BY used_bytes DESC, lower(username)
LIMIT $2::int
`

type TopConsumersParams struct {
	DefaultQuota int64
	MaxRows      int32
}

type TopConsumersRow struct {
	ID         uuid.UUID
	Username   string
	UsedBytes  int64
	QuotaBytes int64
}

func (q *Queries) TopConsumers(ctx context.Context, arg TopConsumersParams) ([]TopConsumersRow, error) {
	rows, err := q.db.Query(ctx, topConsumers, arg.DefaultQuota, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TopConsumersRow{}
	for rows.Next() {
		var i TopConsumersRow
		if err := rows.Scan(
			&i.ID,
			&i.Username,
			&i.UsedBytes,
			&i.QuotaBytes,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

