const upsertStorageSnapshot = `-- name: UpsertStorageSnapshot :exec
INSERT INTO storage_snapshots (day, total_bytes) VALUES (CURRENT_DATE, $1)
ON CONFLICT (day) DO UPDATE SET total_bytes = EXCLUDED.total_bytes
`

func (q *Queries) UpsertStorageSnapshot(ctx context.Context, totalBytes int64) error {
	_, err := q.db.Exec(ctx, upsertStorageSnapshot, totalBytes)
	return err
}
